class Solution:
    def countSubstrings(self, s: str) -> int:
        def expand(left: int, right: int) -> int:
            total = 0
            while left >= 0 and right < len(s) and s[left] == s[right]:
                total += 1
                left -= 1
                right += 1
            return total

        answer = 0
        for center in range(len(s)):
            answer += expand(center, center)
            answer += expand(center, center + 1)
        return answer

